import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import test from "node:test";
import { VERSION } from "../src/version.js";
const rootFile = (relativePath) => fileURLToPath(new URL(`../../${relativePath}`, import.meta.url));
test("release version anchors match the canonical code version", () => {
    const packageJson = JSON.parse(readFileSync(rootFile("package.json"), "utf8"));
    const packageLock = JSON.parse(readFileSync(rootFile("package-lock.json"), "utf8"));
    const infoPlist = readFileSync(rootFile("Start Mac Codex Bridge.app/Contents/Info.plist"), "utf8");
    const readme = readFileSync(rootFile("README.md"), "utf8");
    const changelog = readFileSync(rootFile("CHANGELOG.md"), "utf8");
    const escapedVersion = VERSION.replace(/\./g, "\\.");
    const buildVersion = VERSION.split(".").join("");
    assert.equal(packageJson.version, VERSION, "package.json version drifted");
    assert.equal(packageLock.version, VERSION, "package-lock.json root version drifted");
    assert.equal(packageLock.packages?.[""]?.version, VERSION, "package-lock.json packages[''] version drifted");
    assert.match(infoPlist, new RegExp(`<key>CFBundleShortVersionString</key>\\s*<string>${escapedVersion}</string>`), "macOS short version drifted");
    assert.match(infoPlist, new RegExp(`<key>CFBundleVersion</key>\\s*<string>${buildVersion}</string>`), "macOS build version drifted");
    assert.match(readme, new RegExp(`当前测试候选版本[\\s\\S]{0,100}\\*\\*V${escapedVersion}\\*\\*`), "README candidate version drifted");
    assert.match(changelog, new RegExp(`当前公开版本为 \\*\\*V${escapedVersion}\\*\\*`), "CHANGELOG current-version marker drifted");
    assert.match(changelog, new RegExp(`^## V${escapedVersion}[^\\r\\n]*\\r?\\n\\r?\\n- `, "m"), "CHANGELOG has no populated section heading for the canonical version");
});
